/** A refusal that carries the cyclic path of names, the first repeated at the end. */
export class CycleError extends Error {
  /**
   * @param {string[]} cycle - the names from the re-entered task, through the search stack, back to it.
   */
  constructor(cycle) {
    super(`cycle: ${cycle.join(' -> ')}`)
    this.name = 'CycleError'
    this.cycle = cycle
  }
}

/**
 * The first cycle a depth-first search finds, starting from each task in ascending name
 * order and walking each task's dependencies in ascending name order.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|null} the cyclic names, or null when there is none.
 */
function findCycle(tasks) {
  const names = [...tasks.keys()].sort()
  const visited = new Set()
  const onStack = new Set()
  const stack = []
  let found = null

  function visit(name) {
    if (found !== null || visited.has(name)) return
    if (onStack.has(name)) {
      const index = stack.indexOf(name)
      found = [...stack.slice(index), name]
      return
    }
    onStack.add(name)
    stack.push(name)
    for (const dep of [...tasks.get(name).needs].sort()) {
      visit(dep)
      if (found !== null) break
    }
    stack.pop()
    onStack.delete(name)
    visited.add(name)
  }

  for (const name of names) {
    visit(name)
    if (found !== null) break
  }
  return found
}

/**
 * The tasks in run order: repeatedly the lexicographically smallest task whose
 * dependencies have all been emitted. A cyclic graph has no such task once its
 * cyclic members are all that remain, and is refused instead.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]} the names in run order.
 * @throws {CycleError} when the graph has a dependency cycle.
 */
export function order(tasks) {
  const remaining = new Set(tasks.keys())
  const emitted = new Set()
  const out = []
  while (remaining.size > 0) {
    const ready = [...remaining].filter(name => tasks.get(name).needs.every(need => emitted.has(need))).sort()
    if (ready.length === 0) {
      throw new CycleError(findCycle(tasks))
    }
    remaining.delete(ready[0])
    emitted.add(ready[0])
    out.push(ready[0])
  }
  return out
}
